// pyFloat.mjs
// Faithful reimplementation of CPython's float() string parsing and
// repr()/str() float formatting, so numeric output matches Python exactly.

// Error thrown when a string cannot be converted to a float, mirroring
// Python's `ValueError: could not convert string to float: ...`.
export class FloatParseError extends Error {
  constructor(text) {
    super(`could not convert string to float: ${text}`);
    this.name = 'FloatParseError';
  }
}

// CPython digit-part: digits optionally separated by single underscores
// (PEP 515), e.g. "1_000". Underscores must sit between two digits.
const DIGIT_PART = '\\d(?:_?\\d)*';
const FLOAT_RE = new RegExp(
  `^[+-]?(?:${DIGIT_PART}(?:\\.(?:${DIGIT_PART})?)?|\\.${DIGIT_PART})` +
    `(?:[eE][+-]?${DIGIT_PART})?$`
);
const INF_NAN_RE = /^[+-]?(inf(inity)?|nan)$/i;

// Parse a string the way Python's built-in float() does.
// Throws FloatParseError on failure (argparse turns this into
// "invalid float value" errors).
export function parsePythonFloat(text) {
  const s = text.trim();
  if (INF_NAN_RE.test(s)) {
    const lower = s.toLowerCase();
    const negative = lower.startsWith('-');
    if (lower.includes('nan')) return NaN;
    return negative ? -Infinity : Infinity;
  }
  if (!FLOAT_RE.test(s)) {
    throw new FloatParseError(text);
  }
  return Number(s.replace(/_/g, ''));
}

// Format a finite double exactly like CPython's repr(float):
// shortest round-trip digits, fixed notation when -4 < decpt <= 16,
// scientific notation otherwise (exponent always signed, >= 2 digits).
export function pythonFloatRepr(x) {
  if (Number.isNaN(x)) return 'nan';
  if (x === Infinity) return 'inf';
  if (x === -Infinity) return '-inf';
  if (x === 0) return Object.is(x, -0) ? '-0.0' : '0.0';

  const negative = x < 0;
  const mag = Math.abs(x);

  // toExponential() without an argument yields the shortest string of
  // digits that round-trips to the same double — the same digit sequence
  // CPython's dtoa(mode 0) produces.
  const expForm = mag.toExponential(); // e.g. "1.23456e+2"
  const eIndex = expForm.indexOf('e');
  const mantissa = expForm.slice(0, eIndex);
  const exp10 = parseInt(expForm.slice(eIndex + 1), 10);
  const digits = mantissa.replace('.', '');
  // Value = 0.<digits> * 10^decpt  (dtoa convention)
  const decpt = exp10 + 1;

  let body;
  if (decpt <= -4 || decpt > 16) {
    // Scientific notation: d[.ddd]e±XX
    body = digits[0];
    if (digits.length > 1) body += '.' + digits.slice(1);
    const e = decpt - 1;
    body +=
      'e' + (e < 0 ? '-' : '+') + String(Math.abs(e)).padStart(2, '0');
  } else if (decpt <= 0) {
    body = '0.' + '0'.repeat(-decpt) + digits;
  } else if (decpt >= digits.length) {
    body = digits + '0'.repeat(decpt - digits.length) + '.0';
  } else {
    body = digits.slice(0, decpt) + '.' + digits.slice(decpt);
  }
  return negative ? '-' + body : body;
}

// str(float): identical to repr(float) in Python 3.
export function pythonFloatStr(x) {
  return pythonFloatRepr(x);
}

// pyRepr.mjs
// Reimplementations of Python's repr() for str and bytes objects, used to
// reproduce Python's print() output byte-for-byte.

// repr() of a Python str: single quotes preferred, double quotes when the
// string contains a single quote but no double quote; standard escapes.
export function pythonStrRepr(s) {
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";
  let out = quote;
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (code < 0x20 || code === 0x7f) {
      out += '\\x' + code.toString(16).padStart(2, '0');
    } else out += ch;
  }
  return out + quote;
}

// repr() of a Python bytes object built from a JS string (UTF-8 encoded),
// e.g. b'-3.14159' — this is what print(bytes) shows in Python.
export function pythonBytesRepr(s) {
  const bytes = new TextEncoder().encode(s);
  const hasSingle = bytes.includes(0x27); // '
  const hasDouble = bytes.includes(0x22); // "
  const quoteByte = hasSingle && !hasDouble ? 0x22 : 0x27;
  const quote = String.fromCharCode(quoteByte);
  let out = 'b' + quote;
  for (const b of bytes) {
    if (b === 0x5c) out += '\\\\';
    else if (b === quoteByte) out += '\\' + quote;
    else if (b === 0x09) out += '\\t';
    else if (b === 0x0a) out += '\\n';
    else if (b === 0x0d) out += '\\r';
    else if (b >= 0x20 && b < 0x7f) out += String.fromCharCode(b);
    else out += '\\x' + b.toString(16).padStart(2, '0');
  }
  return out + quote;
}

// canonicalJson.mjs
// Reimplementation of canonicaljson.encode_canonical_json behavior:
// - floats use Python repr() formatting (shortest round-trip)
// - object keys sorted, separators are "," and ":" (no whitespace)
// - non-finite floats are rejected (allow_nan=False)
// The encoder is hand-written; JSON.stringify is intentionally not used.

import { pythonFloatRepr } from './pyFloat.mjs';

// Mirrors Python's ValueError raised by json.encoder for inf/nan.
export class ValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
  }
}

function encodeFloat(x) {
  if (Number.isNaN(x)) {
    throw new ValueError('Out of range float values are not JSON compliant: nan');
  }
  if (!Number.isFinite(x)) {
    throw new ValueError(
      'Out of range float values are not JSON compliant: ' +
        (x > 0 ? 'inf' : '-inf')
    );
  }
  return pythonFloatRepr(x);
}

// JSON string escaping matching Python's json.dumps with ensure_ascii=False.
function encodeString(s) {
  let out = '"';
  for (const ch of s) {
    const code = ch.codePointAt(0);
    if (ch === '"') out += '\\"';
    else if (ch === '\\') out += '\\\\';
    else if (ch === '\b') out += '\\b';
    else if (ch === '\f') out += '\\f';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (code < 0x20) out += '\\u' + code.toString(16).padStart(4, '0');
    else out += ch;
  }
  return out + '"';
}

function encode(value) {
  if (value === null || value === undefined) return 'null';
  if (typeof value === 'boolean') return value ? 'true' : 'false';
  if (typeof value === 'number') return encodeFloat(value);
  if (typeof value === 'string') return encodeString(value);
  if (Array.isArray(value)) {
    return '[' + value.map(encode).join(',') + ']';
  }
  if (typeof value === 'object') {
    const keys = Object.keys(value).sort();
    const parts = keys.map((k) => encodeString(k) + ':' + encode(value[k]));
