// argparse.mjs
// Minimal reimplementation of Python's argparse behavior, matching the
// usage/error/help output, exit codes, and parsing semantics (required
// options, "--opt value" / "--opt=value" forms, unique-prefix abbreviation,
// negative-number handling, "expected one argument", "invalid float value",
// "unrecognized arguments") of the original script.

import { parsePythonFloat, FloatParseError } from './pyFloat.mjs';
import { pythonStrRepr } from './pyRepr.mjs';

// argparse treats a token starting with '-' as a value only when it looks
// like a negative number (the parser defines no negative-number options).
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

function looksLikeOption(token) {
  if (token.length === 0 || token[0] !== '-') return false;
  if (token === '-') return false; // a lone dash is a value
  if (NEGATIVE_NUMBER_RE.test(token)) return false;
  return true;
}

export class ArgumentParser {
  constructor(prog) {
    this.prog = prog;
    // The help option always exists, like argparse's default.
    this.options = [
      { flags: ['-h', '--help'], dest: 'help', isHelp: true, required: false },
    ];
  }

  // addArgument('--a', { required: true, type: 'float' })
  addArgument(flag, { required = false, type = 'string' } = {}) {
    const dest = flag.replace(/^--?/, '');
    const metavar = dest.toUpperCase();
    this.options.push({ flags: [flag], dest, metavar, required, type });
  }

  _invocation(opt) {
    if (opt.isHelp) return '-h, --help';
    return `${opt.flags[0]} ${opt.metavar}`;
  }

  usage() {
    const parts = this.options.map((opt) => {
      const inv = this._invocation(opt);
      return opt.required ? inv : `[${inv.split(' ')[0]}]`.replace('[-h]', '[-h]');
    });
    // help is shown as [-h]; required options without brackets
    const rendered = this.options
      .map((opt) => (opt.isHelp || !opt.required ? `[${opt.isHelp ? '-h' : this._invocation(opt)}]` : this._invocation(opt)))
      .join(' ');
    return `usage: ${this.prog} ${rendered}`;
  }

  helpText() {
    const lines = this.options.map((opt) => ({
      invocation: this._invocation(opt),
      help: opt.isHelp ? 'show this help message and exit' : '',
    }));
    const helpPosition = Math.max(...lines.map((l) => l.invocation.length)) + 2;
    const body = lines
      .map((l) => {
        if (!l.help) return '  ' + l.invocation;
        return '  ' + l.invocation.padEnd(helpPosition) + l.help;
      })
      .join('\n');
    return `${this.usage()}\n\noptions:\n${body}`;
  }

  printHelp() {
    process.stdout.write(this.helpText() + '\n');
  }

  error(message) {
    process.stderr.write(this.usage() + '\n');
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  // Resolve an option name (exact or unique prefix for long options).
  _matchOption(name) {
    for (const opt of this.options) {
      if (opt.flags.includes(name)) return opt;
    }
    if (name.startsWith('--')) {
      const matches = this.options.filter((opt) =>
        opt.flags.some((f) => f.startsWith('--') && f.startsWith(name))
      );
      if (matches.length === 1) return matches[0];
      if (matches.length > 1) {
        const all = matches.flatMap((m) => m.flags).join(', ');
        this.error(`ambiguous option: ${name} could match ${all}`);
      }
    }
    return null;
  }

  parseArgs(argv) {
    const values = {};
    const extras = [];
    let onlyPositional = false;
    let i = 0;

    while (i < argv.length) {
      const token = argv[i];

      if (!onlyPositional && token === '--') {
        onlyPositional = true;
        i += 1;
        continue;
      }

      if (!onlyPositional && looksLikeOption(token)) {
        let name = token;
        let inlineValue = null;
        if (token.startsWith('--')) {
          const eq = token.indexOf('=');
          if (eq !== -1) {
            name = token.slice(0, eq);
            inlineValue = token.slice(eq + 1);
          }
        }

        const opt = this._matchOption(name);
        if (!opt) {
          extras.push(token);
          i += 1;
          continue;
        }

        if (opt.isHelp) {
          if (inlineValue !== null) {
            this.error(
              `argument -h/--help: ignored explicit argument ${pythonStrRepr(inlineValue)}`
            );
          }
          this.printHelp();
          process.exit(0);
        }

        // Option that consumes exactly one argument.
        let raw;
        if (inlineValue !== null) {
          raw = inlineValue;
          i += 1;
        } else {
          const next = argv[i + 1];
          if (next === undefined || looksLikeOption(next)) {
            this.error(`argument ${opt.flags[0]}: expected one argument`);
          }
          raw = next;
          i += 2;
        }

        if (opt.type === 'float') {
          try {
            values[opt.dest] = parsePythonFloat(raw);
          } catch (err) {
            if (err instanceof FloatParseError) {
              this.error(
                `argument ${opt.flags[0]}: invalid float value: ${pythonStrRepr(raw)}`
              );
            }
            throw err;
          }
        } else {
          values[opt.dest] = raw;
        }
      } else {
        extras.push(token);
        i += 1;
      }
    }

    const missing = this.options.filter(
      (opt) => opt.required && !(opt.dest in values)
    );
    if (missing.length > 0) {
      this.error(
        'the following arguments are required: ' +
          missing.map((opt) => opt.flags[0]).join(', ')
      );
    }
    if (extras.length > 0) {
      this.error('unrecognized arguments: ' + extras.join(' '));
    }
    return values;
  }
}

