// test3.mjs
// Node.js (ESM) port of test3.py:
//   parse --a as a float, encode it as canonical JSON, print the resulting
//   bytes object exactly as Python's print() would (e.g. b'-3.14159').

import { ArgumentParser } from './lib/argparse.mjs';
import { encodeCanonicalJson, ValueError } from './lib/canonicalJson.mjs';
import { pythonBytesRepr } from './lib/pyRepr.mjs';

function main() {
  // argparse derives prog from sys.argv[0]'s basename; mirror that with
  // the basename of this script.
  const prog = (process.argv[1] || 'test3.mjs').split('/').pop();

  const parser = new ArgumentParser(prog);
  parser.addArgument('--a', { type: 'float', required: true });
  const args = parser.parseArgs(process.argv.slice(2));

  const data = args.a;
  try {
    // Encode float as canonical JSON (UTF-8 bytes in Python, text here).
    const result = encodeCanonicalJson(data);
    console.log(pythonBytesRepr(result));
  } catch (err) {
    if (err instanceof ValueError) {
      // Python dies with an uncaught ValueError (traceback, exit code 1).
      process.stderr.write(`ValueError: ${err.message}\n`);
      process.exit(1);
    }
    throw err;
  }
}

main();

